/* Compact transition to the women behind AI; book link spans the existing content width. */
.why-women-copy{padding-bottom:24px}
.why-laidies{padding-top:16px}
#why a.why-full-link:not(.inline-link){display:flex;width:100%;justify-content:space-between;gap:24px;padding:14px 30px;margin-top:28px;border:2px solid var(--hp-orange);border-radius:28px;background:var(--hp-ink);color:var(--hp-orange);text-align:left;font-size:clamp(1.1rem,1.6vw,1.45rem)}
.why-full-link>span{max-width:42ch}.why-full-link strong{color:var(--hp-lime)}
.why-full-link>img{display:block;flex:0 0 auto;width:62px;height:94px;object-fit:contain;transform:rotate(5deg)}
@media(max-width:560px){.why-women-copy{padding-bottom:20px}.why-laidies{padding-top:12px}#why a.why-full-link:not(.inline-link){gap:16px;padding:14px 18px;border-radius:22px}.why-full-link>img{width:50px;height:76px}}
